WITH c AS (SELECT user_id FROM users WHERE signup_date BETWEEN DATE '2025-01-06' AND DATE '2025-01-12' AND NOT is_internal),
a AS (SELECT DISTINCT user_id FROM events WHERE event_ts >= TIMESTAMP '2025-01-13' AND event_ts < TIMESTAMP '2025-01-20' AND event_name NOT IN ('email_delivered','push_delivered'))
SELECT 100.0 * count(a.user_id) / count(*) AS pct_active, count(*) AS cohort, count(a.user_id) AS active FROM c LEFT JOIN a USING(user_id);

